    private async Task VerifyDesigner(CatalogResult catalog,ReferenceCatalog references)
    {
        static void Assert(bool value,string message){if(!value)throw new InvalidOperationException(message);}
        await VerifyEquipmentLayout(catalog);var native=catalog.Originals;var chest=native[22416];var weapon=catalog.Items.First(i=>i.ClassId==2&&i.Slot==13);var twoHand=catalog.Items.First(i=>i.ClassId==2&&i.Slot==17);var offHand=catalog.Items.First(i=>i.Slot==14);var ring=catalog.Items.First(i=>i.Slot==11);var trinket=catalog.Items.First(i=>i.Slot==12);
        var lookup=catalog.Items.ToDictionary(i=>i.Id);lookup[chest.Id]=chest;
        OwnedItem Owned(CatalogItem item,int slot,ulong guid)=>new(guid,item.Id,1,0,slot,"Equipped",100,"","",0,0,true);
        var hero=new CharacterInfo(999999,"Design fixture",60,1,false,0);var equipment=new CharacterSnapshot(hero,[Owned(weapon,15,1),Owned(offHand,16,2),Owned(ring,10,3),Owned(ring,11,4),Owned(trinket,12,5),Owned(trinket,13,6)]);
        var two=GearDesign.Replace(equipment,twoHand,15,lookup,60);Assert(two.Removed.Length==2&&two.After.Items.Count(i=>i.Equipped&&i.Slot is 15 or 16)==1,"Two-hand replacement removes main and off-hand");
        var off=GearDesign.Replace(equipment with{Items=[Owned(twoHand,15,1)]},offHand,16,lookup,60);Assert(off.Removed.Single().Slot==15,"Off-hand replacement clears incompatible two-hand");
        Assert(GearDesign.Replace(equipment,ring,10,lookup,60).After.Items.Any(i=>i.Guid==4)&&GearDesign.Replace(equipment,ring,11,lookup,60).After.Items.Any(i=>i.Guid==3),"Either ring slot can be replaced independently");Assert(GearDesign.Replace(equipment,trinket,12,lookup,60).After.Items.Any(i=>i.Guid==6),"Second trinket survives replacement of first");
        var unique=new CatalogItem(new(ring.Fields,StringComparer.OrdinalIgnoreCase){["MaxCount"]="1"});Assert(!GearDesign.Replace(equipment,unique,10,lookup,60).Allowed,"Unique duplicate in another slot is flagged");
        var fields=new Dictionary<string,string>(chest.Fields,StringComparer.OrdinalIgnoreCase){["ID"]="2000000000",["StatModifierBonusStat2"]="7"};fields["StatPercentEditor2"]=catalog.OriginalTooltips.Calculations.AllocationFor(new(fields),2,40,60).ToString();var candidate=new CatalogItem(fields);lookup[candidate.Id]=candidate;var originalGear=new CharacterSnapshot(hero,[Owned(chest,4,10)]);var replaced=GearDesign.Replace(originalGear,candidate,4,lookup,60);Assert(GearDesign.Compare(originalGear,replaced.After,lookup,catalog.OriginalTooltips,60).Single(m=>m.Name=="Stamina").Change=="-3","Comparison shows correct stat loss");
        var unknown=originalGear with{Items=[originalGear.Items[0] with{BonusLists="999999"}]};Assert(GearDesign.Compare(unknown,replaced.After,lookup,catalog.OriginalTooltips,60).Single(m=>m.Name=="Stamina").Change=="[unresolved]","Unsupported instance modifiers never fabricate a stat delta");
        var report=GearDesign.Budget(chest,catalog.Items,catalog.OriginalTooltips,60);Assert(report.Lines.Sum(l=>l.Allocation)==report.Allocation&&report.Peers.All(p=>p.Id!=chest.Id&&p.ItemLevel==chest.ItemLevel&&p.Quality==chest.Quality&&p.Number("SubclassID")==chest.Number("SubclassID")),"Budget uses allocation and exact peers");
        var set=catalog.OriginalTooltips.Sets[523];var first=lookup[set.Members[0]];var second=lookup[set.Members[1]];var setGear=new CharacterSnapshot(hero,[Owned(first,GearDesign.Targets(first).First(),10),Owned(second,GearDesign.Targets(second).First(),11)]);var noSet=new CatalogItem(new(second.Fields,StringComparer.OrdinalIgnoreCase){["ID"]="2000000001",["ItemSet"]="0",["AllowableClass"]="-1"});lookup[noSet.Id]=noSet;var loss=GearDesign.Replace(setGear,noSet,GearDesign.Targets(second).First(),lookup,60);Assert(GearDesign.SetChanges(setGear,loss.After,lookup,catalog.OriginalTooltips).Any(s=>s.Contains("LOSE")&&s.Contains("(2)")),"Replacing a set piece reports lost threshold bonus");
        Assert(GearDesign.PieceTotals([chest],catalog.OriginalTooltips,60).Single(m=>m.Name=="Armor").After=="1027","Set workspace totals use calculated armor");
        var picker=new SpellPicker(references,true);picker.TriggerFilter.SelectedItem="Chance on hit";Assert(picker.VisibleEntries.Any()&&picker.VisibleEntries.All(e=>e.Trigger=="Chance on hit"),"Trigger filter keeps only matching item-effect templates");picker.TriggerFilter.SelectedItem="No item-effect template";Assert(picker.VisibleEntries.All(e=>e.Trigger=="—"),"Unconfigured spells have an explicit trigger-filter choice");picker.TriggerFilter.SelectedItem="Chance on hit";picker.Filters.Effect.SelectedItem=picker.Filters.Effect.Items.Cast<FilterChoice>().Single(c=>c.Id==2);Assert(picker.VisibleEntries.Any()&&picker.VisibleEntries.All(e=>e.EffectTypes.Contains(2)),"Named effect filter combines with trigger filter");picker.Show();await RenderEditorWindow(picker,"spell-picker-filters-preview");picker.Close();Assert(SpellTypeNames.Effect(2).Contains("damage",StringComparison.OrdinalIgnoreCase)&&SpellTypeNames.Aura(3).Contains("Periodic Damage")&&SpellTypeNames.Effect(99999).Contains("Unknown"),"Readable effect/aura names retain explicit unknown fallback");
        var auraPicker=new SpellPicker(references,false);auraPicker.Show();auraPicker.Filters.SearchAuraForVerification("modify crit");var critChoices=auraPicker.Filters.Aura.Items.Cast<FilterChoice>().Where(c=>c.Id>=0).ToArray();Assert(critChoices.Length>0&&critChoices.All(c=>c.Label.Contains("modify",StringComparison.OrdinalIgnoreCase)&&c.Label.Contains("crit",StringComparison.OrdinalIgnoreCase)),"Aura name search finds modify crit choices");auraPicker.Filters.Aura.SelectedItem=critChoices[0];Assert(auraPicker.VisibleEntries.Any()&&auraPicker.VisibleEntries.All(e=>e.AuraTypes.Contains(critChoices[0].Id)),"Selecting searched aura filters set bonus spells");await RenderEditorWindow(auraPicker,"spell-aura-search-preview");auraPicker.Close();
var cloneSource=await ItemCloning.LoadAsync(17182);Assert(cloneSource.Rows["item_modified_appearance"].Count>0&&cloneSource.Rows["item_x_item_effect"].Count>0,"Known weapon fixture has appearance and proc assignments to clone");var cloneDraft=new CatalogItem(new(cloneSource.Item.Current.Fields,StringComparer.OrdinalIgnoreCase){["Display"]="Verification copy of Sulfuras"});
        using(var db=await DatabaseConnection.OpenAsync(CatalogRepository.Database)){
            await ContentEditing.InitializeAsync(db);using(var gate=new MySqlCommand("SELECT GET_LOCK('anocore_studio_forge',8)",db))Assert(Convert.ToInt32(await gate.ExecuteScalarAsync())==1,"Clone verification lock");
            try{using var tx=await db.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);try{var created=await ItemCloning.SaveCoreAsync(db,tx,cloneSource,cloneDraft);var op=await ContentEditing.ReadAsync(db,tx,created.Operation);var scope=JsonSerializer.Deserialize<ContentScope>(op.Scope)!;var after=JsonSerializer.Deserialize<ItemSnapshot>(op.After)!;Assert(created.Id!=17182&&after.Tables["item_sparse"].Single()["Display"]==cloneDraft.Name,"Duplicate uses a new identity and edited name");Assert(after.Tables["item_x_item_effect"].Count==cloneSource.Rows["item_x_item_effect"].Count&&after.Tables["item_modified_appearance"].Count==cloneSource.Rows["item_modified_appearance"].Count,"Clone preserves effect and appearance assignments");Assert(after.Tables["item_x_item_effect"].All(r=>r["ItemID"]==created.Id.ToString()),"Cloned effect links belong to new item");Assert(HistoryActions.Canonical(await ItemCloning.CaptureAsync(db,tx,17182,cloneSource.SourceScope))==HistoryActions.Canonical(cloneSource.SourceExpected),"Source item/effects/appearance unchanged");
                await ContentEditing.ToggleCoreAsync(db,tx,op);var inactive=await ContentEditing.ReadAsync(db,tx,created.Operation);Assert(!inactive.Active&&(await ItemCloning.CaptureAsync(db,tx,created.Id,scope.CopyScope!)).Tables["item_sparse"].Count==0,"Reverting creation removes cloned definition");await ContentEditing.ToggleCoreAsync(db,tx,inactive);var active=await ContentEditing.ReadAsync(db,tx,created.Operation);Assert(active.Active&&active.After==op.After,"Reapply restores same clone identity and immutable definition");var reedit=await ItemEditing.LoadAsync(created.Id,db,tx);var edited=new CatalogItem(new(reedit.Current.Fields,StringComparer.OrdinalIgnoreCase){["Display"]="Second edit of clone"});await ItemEditing.SaveCoreAsync(db,tx,reedit,edited);Assert(reedit.Native is null,"Created item can be reedited without inventing a native original");bool stale=false;try{await ContentEditing.ToggleCoreAsync(db,tx,active);}catch(InvalidOperationException ex)when(ex.Message.StartsWith("Conflict:")){stale=true;}Assert(stale,"Creation revert does not overwrite a later item edit");
            }finally{await tx.RollbackAsync();}}
            finally{using var release=new MySqlCommand("SELECT RELEASE_LOCK('anocore_studio_forge')",db);await release.ExecuteScalarAsync();}
            Assert(HistoryActions.Canonical(await ItemCloning.CaptureAsync(db,null,17182,cloneSource.SourceScope))==HistoryActions.Canonical(cloneSource.SourceExpected),"Clone test left source data unchanged");
        }
        var window=new DesignerWindow(catalog,22416){Owner=this};window.Show();await window.SetVerificationPreview(originalGear);await RenderEditorWindow(window,"gear-comparison-preview");window.SelectVerificationTab(1);await RenderEditorWindow(window,"gear-budget-preview");window.SelectVerificationTab(2);await RenderEditorWindow(window,"set-designer-preview");window.Close();
        await File.WriteAllTextAsync("artifacts/designer-verification.json",JsonSerializer.Serialize(new{checks="Two-hand/off-hand replacement; both ring/trinket slots; unique duplicate warning; exact stat deltas; unsupported instance fallback; set threshold loss; calculated set totals; exact budget peers; readable enums and trigger filtering; new ID duplication with appearance/effect links; immutable source; clone revert/reapply; reedit and stale conflict; all DB test writes rolled back"},new JsonSerializerOptions{WriteIndented=true}));
    }
